insert into public.tiendas (id, nombre, rubro, sector, bio, whatsapp, instagram, color_portada, color_logo, necesidades) values ('t_barberia_alerce', 'Barbería & Estilo Alerce', 'Servicios y Peluquería', 'Alerce Norte', 'Cortes de cabello clásicos y modernos, perfilado de barba y tratamientos capilares. Atención personalizada en local y a domicilio.', '+56987654321', '@estilo_alerce', 4281153352, 4281440149, '{"tieneStock": false, "tieneAgendamiento": true, "tieneVentaPorWhatsApp": true, "tieneProductosAPedido": false, "participaEnFerias": false, "tieneForoComunidad": true}'::jsonb) on conflict (id) do nothing;
insert into public.tiendas (id, nombre, rubro, sector, bio, whatsapp, instagram, color_portada, color_logo, necesidades) values ('t_minimarket_rosa', 'Minimarket Doña Marta', 'Abarrotes y Alimentos', 'Alerce Histórico', 'Frutas y verduras frescas, pan amasado caliente todos los días a las 17:00 hrs, abarrotes, cecinas y bebidas.', '+56991234567', '@minimarket.donamarta', 4286601941, 4292700960, '{"tieneStock": true, "tieneAgendamiento": false, "tieneVentaPorWhatsApp": true, "tieneProductosAPedido": false, "participaEnFerias": false, "tieneForoComunidad": true}'::jsonb) on conflict (id) do nothing;
insert into public.tiendas (id, nombre, rubro, sector, bio, whatsapp, instagram, color_portada, color_logo, necesidades) values ('t_tejidos_austral', 'Tejidos & Lanares Alerce Austral', 'Artesanía y Textil', 'Alerce Sur', 'Piezas únicas tejidas a palillo y telar con lana 100% natural de oveja chilota, teñida con tintes de cortezas nativas.', '+56976543210', '@alerceaustral.tejidos', 4284232027, 4281236827, '{"tieneStock": true, "tieneAgendamiento": false, "tieneVentaPorWhatsApp": true, "tieneProductosAPedido": true, "participaEnFerias": true, "tieneForoComunidad": true}'::jsonb) on conflict (id) do nothing;
